--- Looks up Russian translation for a skill/support gem.
--- Safe fallback: returns original English name if not found.
---@param gemOrName table|string|nil
---@return string|nil
function GemNamesRU:Get(gemOrName)
    if not gemOrName then
        return nil
    end
    local t = type(gemOrName)
    if t == "table" then
        local gid = gemOrName.gameId or gemOrName.id or gemOrName.gemId
        if gid and self.byGameId[gid] then
            return self.byGameId[gid]
        end
        local name = gemOrName.name or gemOrName.nameSpec
        if name then
            if self.byName[name] then
                return self.byName[name]
            end
            local vaalBase = name:match("^Vaal%s+(.+)$")
            if vaalBase and self.byName[vaalBase] then
                return self.byName[vaalBase] .. " ваал"
            end
            return name
        end
        return nil
    elseif t == "string" then
        if self.byName[gemOrName] then
            return self.byName[gemOrName]
        end
        if self.byGameId[gemOrName] then
            return self.byGameId[gemOrName]
        end
        local vaalBase = gemOrName:match("^Vaal%s+(.+)$")
        if vaalBase and self.byName[vaalBase] then
            return self.byName[vaalBase] .. " ваал"
        end
        return gemOrName
    end
    return nil
end

return GemNamesRU
